add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_product_enquiry_form', 20 );

function perfectpixel_product_enquiry_form() {
	global $product;
	if ( ! $product ) {
		return;
	}
	$cfg = array(
		'field'   => '{{enquiry_subject_field}}',
		'subject' => '{{enquiry_subject_prefix}} ' . wp_strip_all_tags( $product->get_name() ) . ( $product->get_sku() ? ' (' . $product->get_sku() . ')' : '' ),
	);
	echo '<div class="perfectpixel-enquiry" style="margin-bottom:1.5em">';
	echo '<button type="button" class="button perfectpixel-enquiry-toggle" aria-expanded="false">' . esc_html( '{{enquiry_button_text}}' ) . '</button>';
	echo '<div class="perfectpixel-enquiry-form" hidden style="margin-top:1em">' . do_shortcode( '{{enquiry_form_shortcode}}' ) . '</div>';
	echo '</div>';
	?>
	<script>
	( function ( cfg ) {
		var wrap = document.querySelector( '.perfectpixel-enquiry' );
		if ( ! wrap ) {
			return;
		}
		var toggle = wrap.querySelector( '.perfectpixel-enquiry-toggle' );
		var form   = wrap.querySelector( '.perfectpixel-enquiry-form' );
		var field  = form.querySelector( '[name="' + cfg.field + '"]' );
		if ( field ) {
			field.value = cfg.subject;
		}
		toggle.addEventListener( 'click', function () {
			form.hidden = ! form.hidden;
			toggle.setAttribute( 'aria-expanded', String( ! form.hidden ) );
		} );
	} )( <?php echo wp_json_encode( $cfg ); ?> );
	</script>
	<?php
}
